new file mode 100644
index 0000000..6a7d86d
--- /dev/null
+++ b/packages/daemon/src/task-completion-policy.ts
@@ -0,0 +1,18 @@
+export interface TaskSnapshot {
+  readonly status: "active" | "in_review" | "done";
+  readonly approvedReviewCount: number;
+  readonly hasConsent: boolean;
+}
+
+export function evaluateCompletionReadiness(snapshot: TaskSnapshot): { ready: boolean; blocker: string | null } {
+  if (snapshot.status !== "in_review") {
+    return { ready: false, blocker: "not_in_review" };
+  }
+  if (snapshot.approvedReviewCount === 0) {
+    return { ready: false, blocker: "missing_approved_review" };
+  }
+  if (!snapshot.hasConsent) {
+    return { ready: false, blocker: "missing_owner_consent" };
+  }
+  return { ready: true, blocker: null };
+}

